"""Build an offline approval document, never the game preview or public site."""
from pathlib import Path
import base64,json,html
root=Path(__file__).resolve().parents[2]
out=root/'quality-reports/v0.6'
def image(rel,alt):
    data=base64.b64encode((root/rel).read_bytes()).decode()
    return f'<img src="data:image/png;base64,{data}" alt="{html.escape(alt)}">'
palette=[('Mint','#88C9B3','Gốm, túi thư'),('Cream','#FFF0D8','Hanji, sân'),('Coral','#F18478','Nari, tương tác'),('Sky','#89B7D8','Nền, gỗ sơn'),('Honey','#E9BB69','Gỗ, ánh đèn'),('Lavender','#B2A0D2','Hoa, mái T2'),('Navy','#293C55','Mái, nét nhấn')]
colors=''.join(f'<div class="swatch"><i style="background:{c}"></i><b>{n}</b><code>{c}</code><small>{role}</small></div>' for n,c,role in palette)
chars=image('concepts/v0.6/nari-chibi-directions.png','Ba concept Nari A học sinh, B đưa thư, C cư dân thủ công; mỗi concept có mặt trước/bên, silhouette và ba biểu cảm')
town=image('concepts/v0.6/town-and-material-directions.png','Hai quảng trường T1 sân mở và T2 sân vườn, kèm bảy mẫu vật liệu')
before=''.join('<figure>'+image('quality-reports/v0.6/baseline/'+n,a)+'<figcaption>'+a+'</figcaption></figure>' for n,a in [('hero-medium.png','v0.5 · Day / Medium'),('hero-night.png','v0.5 · Night / Low'),('nari-v05.png','v0.5 · Nari thật')])
document='''<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Korean Arena v0.6 — Duyệt concept</title><link rel="icon" href="data:,"><style>
*{box-sizing:border-box}body{margin:0;background:#f5f1e8;color:#293c55;font:16px/1.5 Arial,sans-serif}main{max-width:1320px;margin:auto;padding:24px}section{background:#fffdf8;border:1px solid #dfdfd6;border-radius:20px;padding:24px;margin:0 0 28px}header{display:flex;justify-content:space-between;align-items:center;gap:20px}header b{letter-spacing:.08em;font-size:13px}.tag{background:#d9ede4;border-radius:20px;padding:6px 14px;font-size:13px}h1{font-size:32px;line-height:1.15;margin:12px 0}h2{font-size:25px;margin:8px 0}p{margin:8px 0}img{display:block;width:100%;height:auto;border-radius:12px}.board{margin:14px 0}.note{font-size:14px;color:#58657a}.cols{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.cols article{padding:12px;background:#f4f5ee;border-radius:12px}.colors{display:grid;grid-template-columns:repeat(7,1fr);gap:10px;margin:18px 0}.swatch i{display:block;height:60px;border-radius:12px;border:1px solid #0001;margin-bottom:8px}.swatch b,.swatch code,.swatch small{display:block}.swatch code{font-size:12px}table{width:100%;border-collapse:collapse;margin:18px 0}th,td{border-bottom:1px solid #dadfd9;padding:10px;text-align:left;vertical-align:top}th{background:#edf3ed}figure{margin:0}figcaption{font-size:13px;text-align:center}.decision{border-left:5px solid #f18478;padding:12px 18px;background:#fff1e4;margin:18px 0}a{color:#294e79}@media(max-width:700px){main{padding:10px}section{padding:15px}.cols{grid-template-columns:1fr}.colors{grid-template-columns:repeat(3,1fr)}h1{font-size:26px}table{font-size:12px}th,td{padding:6px}}@page{size:A4 landscape;margin:10mm}@media print{body{background:white;font-size:10px;line-height:1.35}main{padding:0;max-width:none}section{break-after:page;break-inside:avoid;border:0;border-radius:0;padding:0;margin:0}section:last-child{break-after:auto}.board{margin:8px 0}h1{font-size:20px}h2{font-size:18px}header b,.tag,.note{font-size:10px}.board img{width:auto;max-width:100%;max-height:124mm;margin:auto}.cols{gap:10px}.cols article{padding:8px}table{margin:10px 0}th,td{padding:6px}.colors{margin:12px 0}.swatch i{height:12mm}.decision{margin:12px 0}.before img{max-height:90mm;object-fit:contain}.tag{padding:4px 10px}}
</style></head><body><main>
<section><header><b>KOREAN ARENA / PLAYFUL HANGEUL TOWN</b><span class="tag">v0.6 · CONCEPT APPROVAL</span></header><h1>Nari chibi — ba hướng để chọn</h1><p>Đề xuất <b>B · Messenger</b>: giữ bản sắc giấy hanji và túi thư, ưu tiên gương mặt lớn, động tác rõ.</p><div class="board">'''+chars+'''</div><div class="cols"><article><b>A · Student</b><br>Mint / navy · tóc bob + balô<br>Dễ gần, chân rõ; cần tránh dáng quá phổ thông.<br>Độ khó3/5 · dự kiến6,5–8,5ktri.</article><article><b>B · Messenger — đề xuất</b><br>Coral / cream / mint · giấy gấp + túi thư<br>Dáng riêng, giữ Nari; kiểm tra túi/khủy tay.<br>Độ khó3,5/5 · dự kiến8–9,5ktri.</article><article><b>C · Maker</b><br>Lavender / honey · mũ mềm + yếm<br>Cư dân thân thiện; yếm cần thoáng vùng chân.<br>Độ khó4/5 · dự kiến8,5–10ktri.</article></div><p class="note">Concept minh họa, chưa phải model/rig/animation. Mỗi hướng có front, side, silhouette, ba nét mặt và palette. Tỷ lệ production2,5–3đầu; chưa được người dùng duyệt.</p></section>
<section><header><b>HANGEUL TOWN PLAZA / HAI BỐ CỤC</b><span class="tag">T1 — ĐỀ XUẤT</span></header><h1>Một nhà Hanok. Một sân nhỏ để khám phá.</h1><div class="board">'''+town+'''</div><p><b>T1 · Letter Plaza:</b> sân mở, nhà sau-trái, cây/ghế ở rìa; camera và đường chạy rõ. <b>T2 · Craft Court:</b> đường vòng ôm đảo hoa, nhà sau-phải; ấm cúng nhưng dễ che khuất.</p><p class="note">Mái, hoa, grain trong tranh cần giản lược khi dựng. Không phải ảnh game thật hoặc bằng chứng kết cấu bốn mặt. Không xây trọn thị trấn/district mới ở gate này.</p></section>
<section><header><b>MÀU / VẬT LIỆU / NGÂN SÁCH</b><span class="tag">MỤC TIÊU, CHƯA TRIỂN KHAI</span></header><h1>B + T1 — sáng, dễ đọc, nhẹ hơn</h1><div class="colors">'''+colors+'''</div><p>Khối bo có thiết kế, vật liệu matte, palette/vertex color, atlas mặt512px; world atlas512–1024px chỉ khi cần. Không HDRI/bloom nặng; đèn emissive và fill sáng, không để mặt chìm vào tối. Hex sRGB là chuẩn; màu trong tranh chỉ gần đúng.</p><table><thead><tr><th>Chỉ số</th><th>v0.5 thực đo / GLB inspection</th><th>B+T1 ngân sách dự kiến</th></tr></thead><tbody><tr><td>World / character geometry</td><td>75.514 /23.794tri</td><td>30–38k /8–9,5ktri; hướng tới≤40k /≤10k</td></tr><tr><td>Tổng raw GLB</td><td>8.638.328B</td><td>2,6–3,7MB; hướng tới≤4MB</td></tr><tr><td>Medium frame draws, kể cả shadow</td><td>133</td><td>70–95; ưu tiên&lt;100</td></tr><tr><td>Low draws / frame triangles</td><td>57 /99.012</td><td>Chưa đo; DPR1, bớt cây/hoa, không dynamic shadow</td></tr><tr><td>Medium / High frame triangles</td><td>195.524 /195.524</td><td>Chưa đo; shadow casters có chọn lọc</td></tr><tr><td>CPU/GPU/FPS trên thiết bị thật</td><td>Chưa đo; cloud dùng SwiftShader</td><td>Chưa đo; không hứa30/60FPS</td></tr></tbody></table><div class="cols"><article><b>Tái sử dụng</b><br>Input/controller, fixed-step physics, mixer/clip contract, morph semantics, camera, cửa, reduced-motion/visibility/quality/fallback, export/QA pipeline.</article><article><b>Cần làm lại có kiểm soát</b><br>Topology/skin chibi, tỷ lệ và stride, eye gaze/dance, atlas đơn giản, collision kích thước mới, framing. Không scale nhân vật cũ rồi gọi là thiết kế mới.</article><article><b>Đánh đổi T2</b><br>World34–40ktri /2,2–2,8MB. Full Medium85–110draw dự kiến; có thể phải giảm đảo hoa/tán/shadow để dưới100. Không phải số đã benchmark.</article></div><p class="note">MB =1.000.000bytes. Raw GLB khác HTTP transfer hoặc tổng HTML. v0.5 HTML13.543.219B. Các mục tiêu v0.6 chỉ được xác nhận sau export và render thật.</p></section>
<section><header><b>BASELINE THẬT / PHẠM VI SAU DUYỆT</b><span class="tag">V0.5 VẪN GIỮ NGUYÊN</span></header><h1>Từ kiến trúc trang trọng sang sân chơi thân thiện</h1><div class="cols before">'''+before+'''</div><p class="note">Ba ảnh trên là ảnh browser thực tế của v0.5 công khai, được mở kiểm tra trong đợt audit. Hai bảng trước là concept v0.6, không phải ảnh after/gameplay hoàn thiện. Cả hai GLB v0.5 Validator0lỗi/0cảnh báo; Blender sources mở read-only.</p><h2>Prototype đầu tiên, chỉ sau khi chọn concept</h2><p>Một chibi đã duyệt + một nhà bốn mặt + một plaza. Idle/walk/run/jump/landing/greeting, Happy/Surprised/Celebration; một đèn tương tác, camera, keyboard/touch, quality và fallback. Khóa graybox/đỡ mái/cửa/floor trước material polish; kiểm tra skin, retarget và foot contact theo chiều dài chân mới.</p><p>QA sẽ cần front/side/rear, walk/run/jump, ba nét mặt, nhà bốn phía, day/night, desktop/mobile, Low/Med/High, console, reduced-motion, fallback, Validator/build và before/after thật. Chưa có prototype, Blender/GLB hay animation v0.6.</p><div class="decision"><b>Đề xuất duyệt: B + T1.</b><br>Có thể chọn A/B/C kết hợp T1/T2 hoặc yêu cầu chỉnh concept. Chờ xác nhận lựa chọn theo mục4/12 của yêu cầu; không dựng lại toàn bộ trước duyệt. Xuất bản v0.6 cần phê duyệt riêng theo mục16.</div><p>Checkpoint khởi đầu v0.5:5578f5f · tag checkpoint/v0.5-public-verified. Toàn bộ2.335tệp baseline ngoài năm session records được bảo vệ bằng checksum. Giữ nguồn, models, maps, clips, artifacts, package locks và Pages workflow.</p><p class="note">Chi tiết, provenance và exact prompts: concepts/v0.6/CONCEPT_REVIEW.md. Phạm vi: docs/reviews/ART_PIVOT_V06_USER_REQUEST.md. Không có tài sản bên thứ ba/game được tải vào concept, không cài package mới, không backend/multiplayer hay district tương lai.</p></section></main></body></html>'''
(out/'concept-review.html').write_text(document)
(root/'concepts/v0.6/palette.json').write_text(json.dumps({'status':'PROPOSED_NOT_APPROVED','color_space':'sRGB','colors':[{'name':n,'hex':c,'role':role} for n,c,role in palette]},ensure_ascii=False,indent=2)+'\n')
print('Standalone review HTML saved; two original concept boards + three unchanged real baseline PNGs embedded. Not a game build.')
